mapper.select:
SELECT
FROM prd_document p JOIN app_user u ON u.id = p.owner_id WHERE
AND p.title ILIKE '%' || #{query} || '%'
AND p.status = #{status}
ORDER BY p.updated_at DESC, p.id LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM prd_document p WHERE
AND p.title ILIKE '%' || #{query} || '%'
AND p.status = #{status}

mapper.update:
UPDATE prd_document
title = #{title}, status = #{status}, updated_at = now()
WHERE id = #{id}

UPDATE prd_document
SET owner_id = #{ownerId}, updated_at = now()
WHERE id = #{id}
